  "p.frontier.says":
    "يقيّم المولِّد كل خطة يمكنك قراءتها بنتيجتها الذكية ويسعّرها ببنود ميزانيتها، ثم يأخذ الخطط حسب النتيجة لكل وحدة تكلفة حتى ينفد السقف. تؤخذ الخطط الواجب تضمينها أولًا، مهما كانت تكلفتها. تُستبعد الخطة التي لا نتيجة ذكية لها؛ والخطة التي لا بنود ميزانية لها لا تكلّف شيئًا. ليس الاختيار دائمًا الأفضل الممكن، لذا يُعلَّم السقف الذي لا يشتري قيمة أكثر من سقف أرخص ولا يُخفى.",
