  "p.hammock.heading": "المهام الشاملة: مهام موجزة تمتد على غيرها",
  "p.hammock.says":
    "المهمة الشاملة موجز تأتي تواريخه من مهام هذه الخطة التي يربطها، من أبكر بداية إلى آخر نهاية. وهي ليست في شبكة التبعيات، فلا تغيّر أبدًا فسحة أي مهمة ولا النهاية. لا تصبح المهمة شاملة إلا إذا لم تكن لها مدة ولا عمل ولا قيد ولا تبعية، وتُمحى بدايتها المخططة؛ وإعادتها مهمة تزيل كل روابطها. ترتبط المهمة الشاملة بمهمة أو بمهمة شاملة أخرى في هذه الخطة، لا بنفسها، ولا مرتين، ولا في حلقة.",
